88: void Database::Schedule(Work_Callback callback, Baton* baton, bool exclusive) {
89:     Napi::Env env = this->Env();
90:     Napi::HandleScope scope(env);
91: 
92:     if (!open && locked) {
93:         EXCEPTION(Napi::String::New(env, "Database is closed"), SQLITE_MISUSE, exception);
94:         Napi::Function cb = baton->callback.Value();
95:         // We don't call the actual callback, so we have to make sure that
96:         // the baton gets destroyed.
97:         delete baton;
98:         if (!cb.IsUndefined() && cb.IsFunction()) {
99:             Napi::Value argv[] = { exception };
100:             TRY_CATCH_CALL(Value(), cb, 1, argv);
101:         }
102:         else {
103:             Napi::Value argv[] = { Napi::String::New(env, "error"), exception };
104:             EMIT_EVENT(Value(), 2, argv);
105:         }
106:         return;
107:     }
108: 
109:     if (!open || ((locked || exclusive || serialize) && pending > 0)) {
110:         queue.push(new Call(callback, baton, exclusive || serialize));
111:     }
112:     else {
113:         locked = exclusive;
114:         callback(baton);
115:     }
116: }
