591:                 Napi::Value argv[] = { env.Null(), result };
592:                 TRY_CATCH_CALL(stmt->Value(), cb, 2, argv);
593:             }
594:             else {
595:                 // There were no result rows.
596:                 Napi::Value argv[] = {
597:                     env.Null(),
598:                     Napi::Array::New(env, 0)
599:                 };
600:                 TRY_CATCH_CALL(stmt->Value(), cb, 2, argv);
601:             }
602:         }
603:     }
604: 
605:     STATEMENT_END();
606: }
