608: Napi::Value Statement::Each(const Napi::CallbackInfo& info) {
609:     Napi::Env env = info.Env();
610:     Statement* stmt = this;
611: 
612:     int last = info.Length();
613: 
614:     Napi::Function completed;
615:     if (last >= 2 && info[last - 1].IsFunction() && info[last - 2].IsFunction()) {
616:         completed = info[--last].As<Napi::Function>();
617:     }
618: 
619:     EachBaton* baton = stmt->Bind<EachBaton>(info, 0, last);
620:     if (baton == NULL) {
621:         Napi::Error::New(env, "Data type is not supported").ThrowAsJavaScriptException();
622:         return env.Null();
623:     }
624:     else {
625:         baton->completed.Reset(completed, 1);
626:         stmt->Schedule(Work_BeginEach, baton);
627:         return info.This();
628:     }
629: }
